    ('Гродно',       (SELECT id FROM countries WHERE name = 'Республика Беларусь'              AND is_deleted = FALSE LIMIT 1), 'Город на реке Неман, на западе Беларуси. Один из самых красивых исторических городов страны.',                                               373000,   142.20,   '1005-01-01'),
    ('Москва',       (SELECT id FROM countries WHERE name = 'Российская Федерация'             AND is_deleted = FALSE LIMIT 1), 'Столица Российской Федерации и крупнейший город страны. Политический, экономический и культурный центр.',                                    13010000, 2561.50,  '1147-04-04'),
