    ('Варшава',      (SELECT id FROM countries WHERE name = 'Польша'                           AND is_deleted = FALSE LIMIT 1), 'Столица Польши, расположена на реке Висла. Крупный деловой и культурный центр Центральной Европы.',                                            1860000,  517.24,   '1300-01-01'),
    ('Париж',        (SELECT id FROM countries WHERE name = 'Французская Республика'           AND is_deleted = FALSE LIMIT 1), 'Столица Франции и один из самых посещаемых городов мира. Известен Эйфелевой башней, Лувром и богатой культурной жизнью.',                      2161000,  105.40,   '0987-01-01'),
    ('Рим',          (SELECT id FROM countries WHERE name = 'Итальянская Республика'           AND is_deleted = FALSE LIMIT 1), 'Вечный город. Столица Италии и бывшая столица Римской империи. Содержит наибольшее количество исторических памятников в мире.',               2873000,  1287.36,  '0753-04-21'),
    ('Мадрид',       (SELECT id FROM countries WHERE name = 'Королевство Испания'              AND is_deleted = FALSE LIMIT 1), 'Столица Испании. Известна музеем Прадо и футбольным клубом «Реал Мадрид».',                                                                    3305000,  604.45,   '0852-01-01'),
    ('Нью-Йорк',     (SELECT id FROM countries WHERE name = 'Соединённые Штаты Америки'        AND is_deleted = FALSE LIMIT 1), 'Крупнейший город США. Известен Манхэттеном, статуей Свободы и Бродвеем.',                                                                        8336000,  783.84,   '1626-01-01'),
    ('Токио',        (SELECT id FROM countries WHERE name = 'Япония'                           AND is_deleted = FALSE LIMIT 1), 'Столица Японии и крупнейший мегаполис мира. Сочетает ультрасовременные технологии с многовековыми традициями.',                                13960000, 2194.00,  '1457-01-01'),
    ('Мумбаи',       (SELECT id FROM countries WHERE name = 'Республика Индия'                 AND is_deleted = FALSE LIMIT 1), 'Финансовая столица Индии. Крупнейший город страны, центр индийской киноиндустрии — Болливуда.',                                                  20667000, 603.40,   '1507-01-01'),
    ('Торонто',      (SELECT id FROM countries WHERE name = 'Канада'                           AND is_deleted = FALSE LIMIT 1), 'Крупнейший город Канады. Один из самых многонациональных городов мира. Символ — Си-эн Тауэр.',                                                   2794000,  630.20,   '1793-08-27'),
    ('Сидней',       (SELECT id FROM countries WHERE name = 'Австралийский Союз'               AND is_deleted = FALSE LIMIT 1), 'Крупнейший город Австралии. Известен оперным театром и мостом Харбор-Бридж. Принимал Олимпийские игры 2000 года.',                              5312000,  12367.70, '1788-01-26'),
    ('Буэнос-Айрес', (SELECT id FROM countries WHERE name = 'Аргентинская Республика'          AND is_deleted = FALSE LIMIT 1), 'Столица Аргентины. Родина танго. Крупнейший испаноязычный город мира по культурному влиянию.',                                                    3054000,  203.00,   '1536-02-02'),
    ('Йоханнесбург', (SELECT id FROM countries WHERE name = 'Южно-Африканская Республика'      AND is_deleted = FALSE LIMIT 1), 'Крупнейший город ЮАР. Финансовый и экономический центр Африки. Основан в 1886 году во время золотой лихорадки.',                                 5635000,  1645.00,  '1886-09-04'),
    ('Амстердам',    (SELECT id FROM countries WHERE name = 'Королевство Нидерланды'           AND is_deleted = FALSE LIMIT 1), 'Столица Нидерландов. Известен сетью каналов, музеем Ван Гога и Рейксмюсеем.',                                                                     921000,   219.40,   '1275-10-27'),
    ('Мехико',       (SELECT id FROM countries WHERE name = 'Мексиканские Соединённые Штаты'   AND is_deleted = FALSE LIMIT 1), 'Столица Мексики. Один из крупнейших мегаполисов мира. Построен на месте ацтекской столицы Теночтитлан.',                                          9209944,  1485.49,  '1325-01-01'),
    ('Сеул',         (SELECT id FROM countries WHERE name = 'Республика Корея'                 AND is_deleted = FALSE LIMIT 1), 'Столица Южной Кореи. Один из наиболее технологически развитых городов мира. Крупный центр K-культуры.',                                           9776000,  605.21,   '0018-01-01');